        });
        if (insertError) {
          console.error(`[generate-daily-pins] DB insert failed for booking #${booking.id}:`, insertError.message);
          generateResults.push({
            bookingId: booking.id,
            success: false,
            error: insertError.message,
          });
          continue;
        }
